use axum::{extract::{Path, State}, response::IntoResponse, Json};
use uuid::Uuid;
use crate::application::dto::LoanResponse;
use crate::application::error::ApiError;
use crate::app_state::AppState;

pub struct LoanHandler;

impl LoanHandler {
    #[tracing::instrument(skip(state), fields(loan_id = %loan_id))]
    pub async fn get(
        State(state): State<AppState>,
        Path(loan_id): Path<Uuid>,
    ) -> Result<Json<LoanResponse>, ApiError> {
        // BUG: .unwrap() on a Result inside a request path crashes the handler thread on any DB error.
        let loan = state.loan_repo.get_by_id(loan_id).await.unwrap();
        Ok(Json(LoanResponse::from(loan)))
    }
}
